"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=-39.54, corner1_v=-20.1,
    corner2_u=-39.63, corner2_v=20.17,
    corner3_u=39.68, corner3_v=20.05,
    corner4_u=39.06, corner4_v=-20.16,
    hole1_u=-31.76, hole1_v=-12.22, hole1_diameter=6.03,
    hole2_u=-31.74, hole2_v=12.09, hole2_diameter=6.0,
    hole3_u=31.39, hole3_v=-12.25, hole3_diameter=5.99,
    hole4_u=31.75, hole4_v=11.98, hole4_diameter=6.06,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).circle(hole1_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).circle(hole2_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole3_u, hole3_v, -1)).circle(hole3_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole4_u, hole4_v, -1)).circle(hole4_diameter / 2).extrude(thickness + 2))
    return part
